CREATE TABLE IF NOT EXISTS campus_finance_file(id VARCHAR(36) PRIMARY KEY,mime VARCHAR(30) NOT NULL,content MEDIUMBLOB NOT NULL,actor_id BIGINT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS campus_finance_batch(id VARCHAR(40) PRIMARY KEY,kind VARCHAR(16) NOT NULL,merchant_id BIGINT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'OPEN',source_name VARCHAR(150) NULL,source_hash VARCHAR(64) NULL,source_file_id VARCHAR(36) NULL,total_count INT NOT NULL DEFAULT 0,difference_count INT NOT NULL DEFAULT 0,created_by BIGINT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,archived_by BIGINT NULL,archived_at DATETIME NULL,FOREIGN KEY(source_file_id) REFERENCES campus_finance_file(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS campus_finance_line(id BIGINT AUTO_INCREMENT PRIMARY KEY,batch_id VARCHAR(40) NOT NULL,category VARCHAR(24) NOT NULL,difference_code VARCHAR(40) NOT NULL,business_key VARCHAR(100) NOT NULL,merchant_serial VARCHAR(64) NULL,campus_order VARCHAR(48) NULL,trade_type VARCHAR(16) NULL,merchant_amount DECIMAL(16,2) NULL,platform_amount DECIMAL(16,2) NULL,merchant_status VARCHAR(20) NULL,platform_status VARCHAR(20) NULL,reason VARCHAR(1000) NOT NULL,snapshot MEDIUMTEXT NOT NULL,handling_status VARCHAR(20) NOT NULL,handled_by BIGINT NULL,handled_at DATETIME NULL,handle_note VARCHAR(1000) NULL,evidence_id VARCHAR(36) NULL,reviewed_by BIGINT NULL,reviewed_at DATETIME NULL,review_note VARCHAR(1000) NULL,KEY ix_finance_batch(batch_id,id),FOREIGN KEY(batch_id) REFERENCES campus_finance_batch(id),FOREIGN KEY(evidence_id) REFERENCES campus_finance_file(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS campus_finance_audit(id BIGINT AUTO_INCREMENT PRIMARY KEY,batch_id VARCHAR(40) NOT NULL,line_id BIGINT NULL,action VARCHAR(20) NOT NULL,actor_id BIGINT NOT NULL,note VARCHAR(1500) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY ix_finance_audit(batch_id,id),FOREIGN KEY(batch_id) REFERENCES campus_finance_batch(id),FOREIGN KEY(line_id) REFERENCES campus_finance_line(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO sys_menu(menu_id,menu_name,parent_id,order_num,url,menu_type,visible,perms,icon,create_by,create_time) VALUES(8100500,'财务对账',8100000,4,'/campus/finance','C','0','campus:finance:view','fa fa-calculator','admin',NOW()),(8100501,'执行内部对账',8100500,1,'#','F','0','campus:finance:run','#','admin',NOW()),(8100502,'导入商户账单',8100500,2,'#','F','0','campus:finance:import','#','admin',NOW()),(8100503,'处理对账差错',8100500,3,'#','F','0','campus:finance:handle','#','admin',NOW()),(8100504,'复核及归档',8100500,4,'#','F','0','campus:finance:review','#','admin',NOW()),(8100505,'导出对账结果',8100500,5,'#','F','0','campus:finance:export','#','admin',NOW());
INSERT INTO sys_role_menu(role_id,menu_id) SELECT r.role_id,m.menu_id FROM sys_role r JOIN sys_menu m ON m.menu_id BETWEEN 8100500 AND 8100505 WHERE r.role_id IN(1812120000000001,910002) AND NOT EXISTS(SELECT 1 FROM sys_role_menu x WHERE x.role_id=r.role_id AND x.menu_id=m.menu_id);
